def _get_column_array(self, i: int) -> ArrayLike:
    """
        Get the values of the i'th column (ndarray or ExtensionArray, as stored
        in the Block)
        """
    return self._mgr.iget_values(i)

def __getitem__(self, key):
    check_deprecated_indexers(key)
    key = lib.item_from_zerodim(key)
    key = com.apply_if_callable(key, self)
    if is_hashable(key) and (not is_iterator(key)):
        if self.columns.is_unique and key in self.columns:
            if isinstance(self.columns, MultiIndex):
                return self._getitem_multilevel(key)
            return self._get_item_cache(key)
    indexer = convert_to_index_sliceable(self, key)
    if indexer is not None:
        if isinstance(indexer, np.ndarray):
            indexer = lib.maybe_indices_to_slice(indexer.astype(np.intp, copy=False), len(self))
            if isinstance(indexer, np.ndarray):
                return self.take(indexer, axis=0)
        return self._slice(indexer, axis=0)
    if isinstance(key, DataFrame):
        return self.where(key)
    if com.is_bool_indexer(key):
        return self._getitem_bool_array(key)
    is_single_key = isinstance(key, tuple) or not is_list_like(key)
    if is_single_key:
        if self.columns.nlevels > 1:
            return self._getitem_multilevel(key)
        indexer = self.columns.get_loc(key)
        if is_integer(indexer):
            indexer = [indexer]
    else:
        if is_iterator(key):
            key = list(key)
        indexer = self.columns._get_indexer_strict(key, 'columns')[1]
    if getattr(indexer, 'dtype', None) == bool:
        indexer = np.where(indexer)[0]
    data = self._take_with_is_copy(indexer, axis=1)
    if is_single_key:
        if data.shape[1] == 1 and (not isinstance(self.columns, MultiIndex)):
            return data._get_item_cache(key)
    return data

def _getitem_bool_array(self, key):
    if isinstance(key, Series) and (not key.index.equals(self.index)):
        warnings.warn('Boolean Series key will be reindexed to match DataFrame index.', UserWarning, stacklevel=find_stack_level())
    elif len(key) != len(self.index):
        raise ValueError(f'Item wrong length {len(key)} instead of {len(self.index)}.')
    key = check_bool_indexer(self.index, key)
    indexer = key.nonzero()[0]
    return self._take_with_is_copy(indexer, axis=0)

def _getitem_multilevel(self, key):
    loc = self.columns.get_loc(key)
    if isinstance(loc, (slice, np.ndarray)):
        new_columns = self.columns[loc]
        result_columns = maybe_droplevels(new_columns, key)
        if self._is_mixed_type:
            result = self.reindex(columns=new_columns)
            result.columns = result_columns
        else:
            new_values = self.values[:, loc]
            result = self._constructor(new_values, index=self.index, columns=result_columns)
            result = result.__finalize__(self)
        if len(result.columns) == 1:
            top = result.columns[0]
            if isinstance(top, tuple):
                top = top[0]
            if top == '':
                result = result['']
                if isinstance(result, Series):
                    result = self._constructor_sliced(result, index=self.index, name=key)
        result._set_is_copy(self)
        return result
    else:
        return self._ixs(loc, axis=1)

def __setitem__(self, key, value):
    key = com.apply_if_callable(key, self)
    indexer = convert_to_index_sliceable(self, key)
    if indexer is not None:
        return self._setitem_slice(indexer, value)
    if isinstance(key, DataFrame) or getattr(key, 'ndim', None) == 2:
        self._setitem_frame(key, value)
    elif isinstance(key, (Series, np.ndarray, list, Index)):
        self._setitem_array(key, value)
    elif isinstance(value, DataFrame):
        self._set_item_frame_value(key, value)
    elif is_list_like(value) and (not self.columns.is_unique) and (1 < len(self.columns.get_indexer_for([key])) == len(value)):
        self._setitem_array([key], value)
    else:
        self._set_item(key, value)

def _setitem_slice(self, key: slice, value):
    self._check_setitem_copy()
    self.iloc[key] = value

def _setitem_array(self, key, value):
    if com.is_bool_indexer(key):
        if len(key) != len(self.index):
            raise ValueError(f'Item wrong length {len(key)} instead of {len(self.index)}!')
        key = check_bool_indexer(self.index, key)
        indexer = key.nonzero()[0]
        self._check_setitem_copy()
        if isinstance(value, DataFrame):
            value = value.reindex(self.index.take(indexer))
        self.iloc[indexer] = value
    elif isinstance(value, DataFrame):
        check_key_length(self.columns, key, value)
        for k1, k2 in zip(key, value.columns):
            self[k1] = value[k2]
    elif not is_list_like(value):
        for col in key:
            self[col] = value
    elif isinstance(value, np.ndarray) and value.ndim == 2:
        self._iset_not_inplace(key, value)
    elif np.ndim(value) > 1:
        value = DataFrame(value).values
        return self._setitem_array(key, value)
    else:
        self._iset_not_inplace(key, value)

def _iset_not_inplace(self, key, value):

    def igetitem(obj, i: int):
        if isinstance(obj, np.ndarray):
            return obj[..., i]
        else:
            return obj[i]
    if self.columns.is_unique:
        if np.shape(value)[-1] != len(key):
            raise ValueError('Columns must be same length as key')
        for i, col in enumerate(key):
            self[col] = igetitem(value, i)
    else:
        ilocs = self.columns.get_indexer_non_unique(key)[0]
        if (ilocs < 0).any():
            raise NotImplementedError
        if np.shape(value)[-1] != len(ilocs):
            raise ValueError('Columns must be same length as key')
        assert np.ndim(value) <= 2
        orig_columns = self.columns
        try:
            self.columns = Index(range(len(self.columns)))
            for i, iloc in enumerate(ilocs):
                self[iloc] = igetitem(value, i)
        finally:
            self.columns = orig_columns

def _setitem_frame(self, key, value):
    if isinstance(key, np.ndarray):
        if key.shape != self.shape:
            raise ValueError('Array conditional must be same shape as self')
        key = self._constructor(key, **self._construct_axes_dict())
    if key.size and (not is_bool_dtype(key.values)):
        raise TypeError('Must pass DataFrame or 2-d ndarray with boolean values only')
    self._check_inplace_setting(value)
    self._check_setitem_copy()
    self._where(-key, value, inplace=True)

def _set_item_frame_value(self, key, value: DataFrame) -> None:
    self._ensure_valid_index(value)
    if key in self.columns:
        loc = self.columns.get_loc(key)
        cols = self.columns[loc]
        len_cols = 1 if is_scalar(cols) else len(cols)
        if len_cols != len(value.columns):
            raise ValueError('Columns must be same length as key')
        if isinstance(self.columns, MultiIndex) and isinstance(loc, (slice, Series, np.ndarray, Index)):
            cols = maybe_droplevels(cols, key)
            if len(cols) and (not cols.equals(value.columns)):
                value = value.reindex(cols, axis=1)
    arraylike = _reindex_for_setitem(value, self.index)
    self._set_item_mgr(key, arraylike)

def _iset_item_mgr(self, loc: int | slice | np.ndarray, value, inplace: bool=False) -> None:
    self._mgr.iset(loc, value, inplace=inplace)
    self._clear_item_cache()

def _set_item_mgr(self, key, value: ArrayLike) -> None:
    try:
        loc = self._info_axis.get_loc(key)
    except KeyError:
        self._mgr.insert(len(self._info_axis), key, value)
    else:
        self._iset_item_mgr(loc, value)
    if len(self):
        self._check_setitem_copy()

def _iset_item(self, loc: int, value) -> None:
    arraylike = self._sanitize_column(value)
    self._iset_item_mgr(loc, arraylike, inplace=True)
    if len(self):
        self._check_setitem_copy()

def _ensure_valid_index(self, value) -> None:
    """
        Ensure that if we don't have an index, that we can create one from the
        passed value.
        """
    if not len(self.index) and is_list_like(value) and len(value):
        if not isinstance(value, DataFrame):
            try:
                value = Series(value)
            except (ValueError, NotImplementedError, TypeError) as err:
                raise ValueError('Cannot set a frame with no defined index and a value that cannot be converted to a Series') from err
        index_copy = value.index.copy()
        if self.index.name is not None:
            index_copy.name = self.index.name
        self._mgr = self._mgr.reindex_axis(index_copy, axis=1, fill_value=np.nan)

