def _count_level(self, level: Level, axis: int=0, numeric_only: bool=False):
    if numeric_only:
        frame = self._get_numeric_data()
    else:
        frame = self
    count_axis = frame._get_axis(axis)
    agg_axis = frame._get_agg_axis(axis)
    if not isinstance(count_axis, MultiIndex):
        raise TypeError(f'Can only count levels on hierarchical {self._get_axis_name(axis)}.')
    if frame._is_mixed_type:
        values_mask = notna(frame).values
    else:
        values_mask = notna(frame.values)
    index_mask = notna(count_axis.get_level_values(level=level))
    if axis == 1:
        mask = index_mask & values_mask
    else:
        mask = index_mask.reshape(-1, 1) & values_mask
    if isinstance(level, int):
        level_number = level
    else:
        level_number = count_axis._get_level_number(level)
    level_name = count_axis._names[level_number]
    level_index = count_axis.levels[level_number]._rename(name=level_name)
    level_codes = ensure_platform_int(count_axis.codes[level_number])
    counts = lib.count_level_2d(mask, level_codes, len(level_index), axis=axis)
    if axis == 1:
        result = self._constructor(counts, index=agg_axis, columns=level_index)
    else:
        result = self._constructor(counts, index=level_index, columns=agg_axis)
    return result

def _reduce(self, op, name: str, *, axis: Axis=0, skipna: bool=True, numeric_only: bool | None=None, filter_type=None, **kwds):
    assert filter_type is None or filter_type == 'bool', filter_type
    out_dtype = 'bool' if filter_type == 'bool' else None
    if numeric_only is None and name in ['mean', 'median']:
        own_dtypes = [arr.dtype for arr in self._mgr.arrays]
        dtype_is_dt = np.array([is_datetime64_any_dtype(dtype) for dtype in own_dtypes], dtype=bool)
        if dtype_is_dt.any():
            warnings.warn('DataFrame.mean and DataFrame.median with numeric_only=None will include datetime64 and datetime64tz columns in a future version.', FutureWarning, stacklevel=find_stack_level())
            predicate = lambda x: not is_datetime64_any_dtype(x.dtype)
            mgr = self._mgr._get_data_subset(predicate)
            self = type(self)(mgr)
    axis = self._get_axis_number(axis)
    labels = self._get_agg_axis(axis)
    assert axis in [0, 1]

    def func(values: np.ndarray):
        return op(values, axis=axis, skipna=skipna, **kwds)

    def blk_func(values, axis=1):
        if isinstance(values, ExtensionArray):
            if not is_1d_only_ea_dtype(values.dtype) and (not isinstance(self._mgr, ArrayManager)):
                return values._reduce(name, axis=1, skipna=skipna, **kwds)
            return values._reduce(name, skipna=skipna, **kwds)
        else:
            return op(values, axis=axis, skipna=skipna, **kwds)

    def _get_data() -> DataFrame:
        if filter_type is None:
            data = self._get_numeric_data()
        else:
            assert filter_type == 'bool'
            data = self._get_bool_data()
        return data
    numeric_only_bool = com.resolve_numeric_only(numeric_only)
    if numeric_only is not None or axis == 0:
        df = self
        if numeric_only_bool:
            df = _get_data()
        if axis == 1:
            df = df.T
            axis = 0
        ignore_failures = numeric_only is None
        res, _ = df._mgr.reduce(blk_func, ignore_failures=ignore_failures)
        out = df._constructor(res).iloc[0]
        if out_dtype is not None:
            out = out.astype(out_dtype)
        if axis == 0 and len(self) == 0 and (name in ['sum', 'prod']):
            out = out.astype(np.float64)
        if numeric_only is None and out.shape[0] != df.shape[1]:
            com.deprecate_numeric_only_default(type(self), name, deprecate_none=True)
        return out
    assert numeric_only is None
    data = self
    values = data.values
    try:
        result = func(values)
    except TypeError:
        data = _get_data()
        labels = data._get_agg_axis(axis)
        values = data.values
        with np.errstate(all='ignore'):
            result = func(values)
        arg_name = 'numeric_only'
        if name in ['all', 'any']:
            arg_name = 'bool_only'
        warnings.warn(f"Dropping of nuisance columns in DataFrame reductions (with '{arg_name}=None') is deprecated; in a future version this will raise TypeError.  Select only valid columns before calling the reduction.", FutureWarning, stacklevel=find_stack_level())
    if hasattr(result, 'dtype'):
        if filter_type == 'bool' and notna(result).all():
            result = result.astype(np.bool_)
        elif filter_type is None and is_object_dtype(result.dtype):
            try:
                result = result.astype(np.float64)
            except (ValueError, TypeError):
                pass
    result = self._constructor_sliced(result, index=labels)
    return result

